// Unwrap .query wrapper if called from an AI tool workflow
const raw = $input.first().json;
const d = raw.query || raw;

// Normalise phone to E.164 (+370XXXXXXXX) for SMS8.io
function toE164(phone) {
  const digits = (phone || '').replace(/\D/g, '');
  if (digits.startsWith('370') && digits.length >= 11) return '+' + digits;
  if (digits.startsWith('8')   && digits.length >= 9)  return '+370' + digits.slice(1);
  if (digits.startsWith('6')   && digits.length >= 8)  return '+370' + digits;
  return phone || '';
}

// Format date: '2026-07-15' => '2026-07-15 (Trečiadienis)'
function formatDate(dateStr) {
  if (!dateStr) return 'nenurodyta';
  const days = ['Sekmadienis','Pirmadienis','Antradienis','Tre\u010diadienis',
                 'Ketvirtadienis','Penktadienis','\u0160e\u0161tadienis'];
  const dt = new Date(dateStr);
  return `${dateStr} (${days[dt.getDay()]})`;
}

// Format time: '14:00:00' => '14:00'
function fmtTime(t) {
  return t ? String(t).substring(0, 5) : '';
}

const phone   = toE164(d.customer_phone);
const name    = (d.customer_name   || '').split(' ')[0];
const date    = formatDate(d.event_date);
const time    = fmtTime(d.event_time);
const address = d.delivery_address || d.city || 'nenurodyta';
const equip   = d.equipment_list   || 'batutas';
const id      = d.booking_id       || '';

// Target: <=160 chars
const msg = `Sveiki, ${name}! U\u017esakymas #${id} patvirtintas. ` +
  `Data: ${date}${time ? ' ' + time : ''}. ` +
  `Adresas: ${address}. ` +
  `\u012eranga: ${equip}. ` +
  `Klausim\u0173: +37060000000`;

return [{ json: { phone, message: msg, booking_id: id, flow: 'confirmation' } }];

