  return phone || '';
}

function fmtTime(t) {
  return t ? String(t).substring(0, 5) : '';
}

const items = $input.all();

if (!items || items.length === 0) {
  return [{ json: { skip: true, message: 'Rytoj n\u0117ra u\u017esakym\u0173 \u2014 SMS nera\u0161omi.' } }];
}

return items.map(item => {
  const b = item.json;
  const phone   = toE164(b.customer_phone);
  const name    = (b.customer_name || '').split(' ')[0];
  const time    = fmtTime(b.event_time);
  const address = b.delivery_address || b.city || 'nenurodyta';
  const equip   = b.equipment_list   || 'batutas';
  const id      = b.id;

  const depositNote = (!b.deposit_paid && b.deposit_amount)
    ? ` Avansas: \u20ac${b.deposit_amount} - laukiame apmok\u0117jimo.`
    : '';

  const msg = `Sveiki, ${name}! Priminimas: rytoj u\u017es. #${id}` +
    `${time ? ', ' + time : ''}, ` +
    `${address}. \u012eranga: ${equip}.${depositNote} Klausim\u0173: +37060000000`;

  return { json: { phone, message: msg, booking_id: id, flow: 'reminder' } };
});

